codeExamples.cpp:
#include <iostream>
double calculateTotal(double price, double taxRate = 0.18) {
    return price + (price * taxRate);
}
int main() {
    double itemCost = 100.0;
    double total = calculateTotal(itemCost);
    std::cout << "Total: $" << total << std::endl;
    return 0;
}
